ALTER TABLE problems ADD COLUMN active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1));
UPDATE problems SET active = 0 WHERE id IN ('courier-settlement', 'shared-cold-delivery', 'bangla-order-notes', 'produce-crates', 'factory-maintenance');

