-- Turn garment offcuts into traceable feedstock
UPDATE problems SET sector = 'circular', places_json = '["gazipur", "dhaka"]', sources_json = '[{"title": "Global Fashion Agenda · Textile-waste sorting in Bangladesh", "url": "https://globalfashionagenda.org/news-article/transforming-post-industrial-textile-waste-in-bangladesh/", "date": "13 March 2026", "en": "A Bangladesh pilot found that sorting at source and reliable composition data helped textile waste reach recyclers. It also reports continuing quality and capacity limits. Reverse Resources already supports traceability in this market.", "bn": "বাংলাদেশের একটি পরীক্ষামূলক উদ্যোগে কারখানায় বাছাই ও কাপড়ের উপাদানের নির্ভরযোগ্য তথ্য রিসাইক্লিংয়ে কাজে এসেছে। মান ও সক্ষমতার সীমাও আছে। Reverse Resources এই বাজারে কাপড়ের গতিপথের তথ্য নিয়ে কাজ করছে।"}]' WHERE id = 'garment-offcuts';
UPDATE problem_text SET title = 'Recyclers need clean, traceable textile offcuts', summary = 'Mixed fabric and uncertain composition make factory waste harder to recycle.', customer = 'Garment factories, established waste handlers and textile recyclers.', context = 'A Bangladesh textile pilot shows the value of source sorting and dependable material records. Traceability platforms already exist. A possible gap is the practical work of qualifying small batches and arranging reliable pickup.', unknown = 'Which material grades will a recycler commit to buying? Do sorting and transport costs leave a margin while paying existing handlers fairly?' WHERE problem_id = 'garment-offcuts' AND locale = 'en';
UPDATE problem_text SET title = 'রিসাইক্লারদের দরকার বাছাই করা কাপড় ও নির্ভরযোগ্য তথ্য', summary = 'কাপড় মিশে গেলে আর উপাদান জানা না থাকলে পুনর্ব্যবহার কঠিন হয়।', customer = 'পোশাক কারখানা, ঝুট ব্যবসায়ী ও টেক্সটাইল রিসাইক্লার।', context = 'বাংলাদেশের একটি উদ্যোগে উৎসে বাছাই ও কাপড়ের সঠিক তথ্য রাখার গুরুত্ব দেখা গেছে। গতিপথের তথ্য রাখার প্ল্যাটফর্ম আগেই আছে। ছোট চালানের মান যাচাই ও সময়মতো সংগ্রহের কাজে কোথায় ঘাটতি আছে, দেখা যেতে পারে।', unknown = 'কোন মানের কাপড় কিনতে রিসাইক্লার আগেই রাজি হবেন? ঝুট ব্যবসায়ীদের ন্যায্য দাম দিয়ে বাছাই ও পরিবহনের খরচের পর লাভ থাকবে কি?' WHERE problem_id = 'garment-offcuts' AND locale = 'bn';
UPDATE approaches SET guides_json = '["validation/customer-interviews", "validation/demand-without-building", "metrics/unit-economics"]' WHERE id = 'garment-offcuts-approach';
UPDATE approach_text SET title = 'Turn garment offcuts into traceable feedstock', summary = 'Match sorted factory offcuts with recyclers who need a specific material.', description = 'Agree on a recycler’s material specification first. Work with a factory and its existing waste handler to separate, weigh and document matching offcuts, then coordinate pickup. Use existing traceability tools where possible.', business_model = 'Charge a handling or matching fee on accepted batches. The buyer’s price must cover sorting, transport, rejected material and fair payment to the supplier.', steps_json = '["Ask two recyclers for their buying specifications, rejection reasons and minimum batch size.", "With one factory and its waste handler, prepare and document a small batch to an agreed specification. Get the recycler’s acceptance before scaling collection.", "Complete one paid delivery. Reconcile accepted weight, rejected material and all costs; ask both sides to repeat it."]', signal = 'A repeat order for a documented grade with a positive margin after rejects and transport.', prototype = 'Build a batch record with material composition, source, weight, quality checks, pickup, accepted weight and buyer. Track who supplied each field. Use fictional batches and avoid unverified recycled-content or certification claims.' WHERE approach_id = 'garment-offcuts-approach' AND locale = 'en';
UPDATE approach_text SET title = 'গার্মেন্টসের ঝুটকে রিসাইক্লিংয়ের কাঁচামাল বানান', summary = 'নির্দিষ্ট কাপড় দরকার এমন রিসাইক্লারের সঙ্গে বাছাই করা ঝুট মিলিয়ে দিন।', description = 'রিসাইক্লার কী ধরনের কাপড় চান, আগে ঠিক করুন। কারখানা ও তার চালু ঝুট ব্যবসায়ীর সঙ্গে মিলে সেই কাপড় আলাদা করুন, ওজন নিন, তথ্য রাখুন এবং সংগ্রহের ব্যবস্থা করুন। সম্ভব হলে চালু ট্র্যাকিং টুল ব্যবহার করুন।', business_model = 'ক্রেতার গ্রহণ করা চালানে সংগ্রহ বা ক্রেতা মেলানোর ফি নিন। বাছাই, পরিবহন, ফেরত যাওয়া কাপড় ও সরবরাহকারীর ন্যায্য দাম মিটিয়েও লাভ থাকতে হবে।', steps_json = '["দুজন রিসাইক্লারের কাছে কাপড়ের মান, ফেরত দেওয়ার কারণ ও ন্যূনতম চালানের পরিমাণ জানুন।", "একটি কারখানা ও তার ঝুট ব্যবসায়ীর সঙ্গে ঠিক করা মানের ছোট চালান তৈরি করে তথ্য রাখুন। সংগ্রহ বাড়ানোর আগে রিসাইক্লার সেটি গ্রহণ করেন কি না দেখুন।", "টাকার বিনিময়ে একটি চালান পৌঁছে দিন। গ্রহণ করা ওজন, ফেরত কাপড় ও সব খরচ মেলান। দুই পক্ষ আবার করতে চান কি না জানুন।"]', signal = 'পরিবহন ও ফেরত কাপড়ের খরচ বাদ দিয়েও লাভ থাকে এবং একই মানের কাপড়ের আবার অর্ডার আসে।', prototype = 'কাপড়ের উপাদান, উৎস, ওজন, মান পরীক্ষা, সংগ্রহ, গ্রহণ করা ওজন ও ক্রেতা নিয়ে চালানের রেকর্ড বানান। কোন তথ্য কে দিয়েছেন, রাখুন। কাল্পনিক চালান ব্যবহার করুন। যাচাই ছাড়া রিসাইক্লিং বা সনদের দাবি করবেন না।' WHERE approach_id = 'garment-offcuts-approach' AND locale = 'bn';

