INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('produce-cold-chain', 'produce-cold-chain', 'agriculture', '["rajshahi", "bogura"]', '[{"title": "FAO · Bangladesh’s crop-storage investment needs", "url": "https://www.fao.org/hand-in-hand/previous-editions/investment-forum-2022/bangladesh/en", "date": "2022 investment plan", "en": "FAO’s investment plan identifies post-harvest losses and storage gaps in several crop chains. Its proposed projects are context for field research, not evidence that a particular cooling service will sell.", "bn": "FAO-এর বিনিয়োগ পরিকল্পনায় কয়েকটি ফসল সংরক্ষণের ঘাটতি ও ফসল তোলার পর নষ্ট হওয়ার কথা আছে। কোনো নির্দিষ্ট সেবার চাহিদা আছে কি না, মাঠে গিয়ে জানতে হবে।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('produce-cold-chain', 'en', 'Fresh produce loses value before reaching buyers', 'Harvested produce needs handling and storage suited to the crop.', 'Grower groups and produce buyers near harvest centres.', 'Bangladesh’s crop-storage investment plans identify losses between harvest and sale. A useful starting point is one crop, one harvest window and a buyer who values better quality.', 'Does cooling improve the seller’s net return after transport, electricity and storage fees? Who pays when produce is rejected, and can the facility earn outside peak harvest?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('produce-cold-chain', 'bn', 'ক্রেতার কাছে পৌঁছানোর আগেই ফসলের দাম কমে যায়', 'ফসলের ধরন অনুযায়ী পরিবহন ও সংরক্ষণের ব্যবস্থা দরকার।', 'ফসল সংগ্রহকেন্দ্রের আশপাশের চাষিদের দল ও পাইকারি ক্রেতা।', 'বাংলাদেশের ফসল সংরক্ষণের বিনিয়োগ পরিকল্পনায় ফসল তোলা থেকে বিক্রির মধ্যে ক্ষতির কথা উঠে এসেছে। একটি ফসল, একটি মৌসুম আর ভালো মানের জন্য বেশি দিতে রাজি একজন ক্রেতা দিয়ে শুরু করা যায়।', 'পরিবহন, বিদ্যুৎ ও সংরক্ষণের খরচ বাদ দিয়ে বিক্রেতার আয় বাড়বে কি? ক্রেতা ফসল ফেরত দিলে ক্ষতি কে নেবে? মৌসুমের বাইরে আয়ের উপায় কী?');
INSERT INTO approaches (id, problem_id, kind, position, added_at, guides_json) VALUES ('harvest-cooling', 'produce-cold-chain', 'service', '0', '2026-09-19', '["validation/customer-interviews", "validation/demand-without-building", "metrics/unit-economics"]');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('harvest-cooling', 'en', 'Cold storage by the crate, near harvest', 'Help growers keep produce saleable while they arrange a buyer.', 'Offer short-term, crop-specific cooling through an existing storage operator. Collect small batches, record their condition and arrange delivery to a committed buyer. Start by coordinating the service before investing in a facility.', 'Grower groups or buyers pay per crate and day. The fee must leave them better off after all handling and delivery costs.', '["Choose one crop and interview five growers and two buyers about recent rejected or spoiled loads.", "With a qualified storage operator, agree on suitable temperatures and run one small paid batch alongside a comparable batch handled as usual.", "Record saleable weight, selling price and every cost. Ask the buyer or grower to book the next batch."]', 'A repeat booking and higher net receipts for the customer after your fee.', 'Build a mobile booking and batch log with crop, crate count, arrival condition, temperature record, buyer, fees and saleable weight. Show net proceeds against a comparison batch. Use no live sensors or payment integrations.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('harvest-cooling', 'bn', 'ফসল তোলার কাছেই ক্রেট হিসেবে হিমাগারের সেবা', 'ক্রেতা ঠিক করতে করতে ফসল যেন নষ্ট না হয়, সে ব্যবস্থা করুন।', 'চালু কোনো হিমাগারের সঙ্গে মিলে অল্প সময়ের জন্য ফসল রাখার সেবা দিন। ছোট চালান সংগ্রহ করুন, অবস্থা লিখে রাখুন এবং আগে ঠিক করা ক্রেতার কাছে পৌঁছে দিন। নিজস্ব হিমাগারে বিনিয়োগের আগে সেবাটি চালিয়ে দেখুন।', 'চাষিদের দল বা ক্রেতা ক্রেট ও দিন হিসেবে ফি দেবেন। সব খরচ মিটিয়েও তাঁদের বাড়তি আয় থাকতে হবে।', '["একটি ফসল বাছুন। সম্প্রতি নষ্ট বা ফেরত যাওয়া চালান নিয়ে পাঁচজন চাষি ও দুজন ক্রেতার সঙ্গে কথা বলুন।", "অভিজ্ঞ হিমাগার পরিচালকের সঙ্গে তাপমাত্রা ঠিক করুন। অল্প ফি নিয়ে একটি ছোট চালান রাখুন; তুলনার জন্য একই রকম আরেকটি চালান আগের নিয়মে রাখুন।", "বিক্রিযোগ্য ওজন, বিক্রির দাম ও সব খরচ লিখুন। ক্রেতা বা চাষি পরের চালানের জন্য আবার বুকিং দেন কি না দেখুন।"]', 'আপনার ফি দেওয়ার পরও গ্রাহকের হাতে বেশি টাকা থাকে, আর তিনি আবার বুকিং দেন।', 'মোবাইলে বুকিং ও চালানের হিসাব রাখার নমুনা বানান। ফসল, ক্রেটের সংখ্যা, আসার সময়ের অবস্থা, তাপমাত্রা, ক্রেতা, ফি ও বিক্রিযোগ্য ওজন রাখুন। তুলনার চালানের সঙ্গে খরচ বাদে আয় দেখান। কোনো সেন্সর বা পেমেন্ট সিস্টেম যুক্ত করবেন না।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('water-system-maintenance', 'water-system-maintenance', 'water', '["khulna"]', '[{"title": "Oxford REACH · SafePani in coastal Bangladesh", "url": "https://reachwater.uk/safepani-a-new-model-to-secure-safe-drinking-water-for-school-children-in-coastal-bangladesh/", "date": "17 March 2023", "en": "REACH documents uncertain water quality and maintenance responsibilities in Khulna schools. SafePani already combines inspections, testing and repairs; its contracting model is a starting point to learn from.", "bn": "খুলনার স্কুলে পানির মান ও রক্ষণাবেক্ষণের দায়িত্ব নিয়ে অনিশ্চয়তার কথা REACH লিখেছে। SafePani পরিদর্শন, পরীক্ষা ও মেরামত একসঙ্গে করছে। তাদের চুক্তির ধরন থেকে শেখা যায়।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('water-system-maintenance', 'en', 'Installed water systems need dependable upkeep', 'A water point is only useful if it keeps delivering safe water.', 'School networks, clinic operators and organisations managing community water systems.', 'Research in coastal Khulna describes water points with unreliable maintenance and quality monitoring. SafePani demonstrates an existing professional-service model. The opportunity is to serve a cluster whose upkeep still lacks a funded owner.', 'Who controls the maintenance budget and can sign a recurring contract? Can a local repair route cover its costs through the dry season?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('water-system-maintenance', 'bn', 'পানির ব্যবস্থা বসালেই কাজ শেষ হয় না', 'নিয়মিত নিরাপদ পানি দিতে না পারলে স্থাপনাটি কাজে আসে না।', 'স্কুলের নেটওয়ার্ক, ক্লিনিক পরিচালনাকারী ও এলাকার পানির ব্যবস্থা দেখভাল করে এমন সংস্থা।', 'উপকূলীয় খুলনার গবেষণায় পানির স্থাপনা রক্ষণাবেক্ষণ ও মান পরীক্ষার অনিশ্চয়তা উঠে এসেছে। SafePani পেশাদার সেবার একটি উদাহরণ। কাছাকাছি কয়েকটি স্থাপনায় নিয়মিত খরচ ও দেখভালের দায়িত্ব নেওয়ার কেউ নেই কি না, খুঁজে দেখুন।', 'রক্ষণাবেক্ষণের বাজেট কার হাতে? নিয়মিত সেবার চুক্তি কে করতে পারবেন? শুষ্ক মৌসুমেও কাছাকাছি স্থাপনা ঘুরে সেবা দিয়ে খরচ উঠবে কি?');
INSERT INTO approaches (id, problem_id, kind, position, added_at, guides_json) VALUES ('reliable-water', 'water-system-maintenance', 'service', '0', '2026-09-19', '["validation/customer-interviews", "validation/demand-without-building", "metrics/unit-economics"]');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('reliable-water', 'en', 'Keep drinking-water systems working', 'Turn testing, repairs and routine upkeep into one dependable service.', 'Maintain a cluster of existing water systems under one service agreement. Pair local technicians with a qualified water-testing laboratory, track breakdowns and give the operator a clear repair history. Learn from SafePani before choosing an unserved area.', 'A school network, water operator or programme funder pays a recurring maintenance fee. Identify the budget holder before recruiting sites.', '["Visit five nearby sites with their operator. Record downtime, repair spending and who authorises payment.", "Agree on a paid trial with one budget holder, a technician and a qualified laboratory. Set repair response times and a procedure for unsafe test results.", "Run the route for a month. Compare downtime, response time and full service cost, then seek a renewal."]', 'A funded renewal and fewer days without a working water supply.', 'Build a site register, fault-report form and technician visit log. Store laboratory results with test date and source. Never infer that water is safe from a sensor value or an overdue test.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('reliable-water', 'bn', 'খাবার পানির ব্যবস্থা সচল রাখার সেবা', 'পানির পরীক্ষা, মেরামত ও নিয়মিত দেখভাল একই সেবায় আনুন।', 'কাছাকাছি কয়েকটি চালু পানির স্থাপনা একটি চুক্তিতে দেখভাল করুন। স্থানীয় মিস্ত্রি ও যোগ্য পরীক্ষাগারকে যুক্ত করুন। কখন কী নষ্ট হলো, কী মেরামত হলো, তার হিসাব রাখুন। এলাকা বাছার আগে SafePani-এর কাজ থেকে শিখুন।', 'স্কুলের নেটওয়ার্ক, পানি সরবরাহকারী বা প্রকল্পের অর্থদাতা নিয়মিত ফি দেবেন। স্থাপনা যুক্ত করার আগে কে টাকা দেবেন, ঠিক করুন।', '["পরিচালকের সঙ্গে কাছাকাছি পাঁচটি স্থাপনা দেখুন। কত দিন বন্ধ থাকে, মেরামতে কত খরচ হয় আর টাকা কে অনুমোদন করেন, লিখুন।", "একজন অর্থদাতা, একজন মিস্ত্রি ও যোগ্য পরীক্ষাগার নিয়ে টাকার বিনিময়ে পরীক্ষামূলক সেবা ঠিক করুন। মেরামতের সময়সীমা ও পানি অনিরাপদ হলে করণীয় স্থির করুন।", "এক মাস সেবা দিন। বন্ধ থাকার সময়, সাড়া দেওয়ার সময় ও মোট খরচ মিলিয়ে দেখুন। এরপর চুক্তি নবায়নের প্রস্তাব দিন।"]', 'পানি না পাওয়ার দিন কমে আসে এবং অর্থদাতা চুক্তি নবায়ন করেন।', 'স্থাপনার তালিকা, ত্রুটি জানানোর ফর্ম ও মিস্ত্রির কাজের হিসাব বানান। পরীক্ষাগারের ফলের সঙ্গে তারিখ ও সোর্স রাখুন। সেন্সরের রিডিং বা পুরোনো পরীক্ষা থেকে পানিকে নিরাপদ বলবেন না।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('missed-follow-up', 'missed-follow-up', 'health', '["anywhere"]', '[{"title": "Simple · Following up with overdue patients", "url": "https://www.simple.org/blog/revealing-data-behind-overdue-patient-calls/", "date": "10 January 2024", "en": "The team behind Simple describes missed hypertension follow-ups in its Bangladesh programme and tools for contacting overdue patients. This supports investigating follow-up workflows, not assuming that another reminder app is needed.", "bn": "Simple-এর দল বাংলাদেশে তাদের কর্মসূচিতে উচ্চ রক্তচাপের রোগীদের ফলোআপ বাদ পড়া ও যোগাযোগের ব্যবস্থা নিয়ে লিখেছে। একই অ্যাপ আবার বানানোর আগে ক্লিনিকের কাজে কোথায় ঘাটতি আছে, জানতে হবে।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('missed-follow-up', 'en', 'Patients miss ongoing care between clinic visits', 'Clinics need a workable way to find and follow up with patients who miss appointments.', 'Private and NGO clinics providing ongoing hypertension care.', 'Simple’s Bangladesh programme documents patients missing follow-up care. Its existing software already supports overdue call lists. A new service needs to solve a clinic’s remaining workflow or staffing gap.', 'Are missed visits driven by reminders, travel, costs or medicine access? What is missing from the clinic’s current tools, and will it pay to fix that gap?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('missed-follow-up', 'bn', 'ক্লিনিকে দেখানোর পর চিকিৎসার ধারাবাহিকতা ভেঙে যায়', 'নির্ধারিত দিনে না আসা রোগীর সঙ্গে যোগাযোগের সহজ ব্যবস্থা দরকার।', 'উচ্চ রক্তচাপের নিয়মিত চিকিৎসা দেয় এমন বেসরকারি ও এনজিও ক্লিনিক।', 'Simple-এর বাংলাদেশের কর্মসূচিতে রোগীদের ফলোআপে না আসার কথা আছে। তাদের সফটওয়্যারে যোগাযোগের তালিকাও আছে। নতুন সেবা করতে হলে ক্লিনিকের কাজে বা লোকবলে বাকি ঘাটতিটি আগে ধরতে হবে।', 'রোগী কি ভুলে যান, নাকি যাতায়াত, খরচ বা ওষুধ না পাওয়া বাধা? চালু ব্যবস্থায় কী নেই? সেই ঘাটতি মেটাতে ক্লিনিক টাকা দেবে কি?');
INSERT INTO approaches (id, problem_id, kind, position, added_at, guides_json) VALUES ('clinic-follow-up', 'missed-follow-up', 'software', '0', '2026-09-19', '["validation/customer-interviews", "validation/demand-without-building", "metrics/unit-economics"]');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('clinic-follow-up', 'en', 'Help clinics bring patients back for follow-up', 'Give clinic staff a simple way to track missed visits and arrange the next one.', 'Build around one clinic’s existing records: who is due, who was contacted and who returned. Reuse tools such as Simple where they fit. Focus on the staff handoff and appointment workflow; clinicians keep control of care.', 'Clinics pay a monthly fee for setup and ongoing support if the service saves staff time or improves continuity of care.', '["Observe one clinic’s follow-up process with permission. Ask staff and willing patients why visits are missed.", "Use fictional records to test a short call list with staff. Compare it with the tools they already use before building.", "With clinic approval and patient consent, run a small trial through one follow-up cycle. Track staff time, completed contacts and return visits using only necessary data."]', 'Staff keep using the workflow, and the clinic agrees to pay for the next cycle.', 'Prototype a staff-only appointment list with synthetic patients, due dates and contact outcomes. No clinical recommendations, real patient data or live messaging. Support role-limited access and deletion in the design.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('clinic-follow-up', 'bn', 'রোগীকে ফলোআপে ফেরাতে ক্লিনিককে সাহায্য করুন', 'বাদ পড়া সাক্ষাৎ ও পরের তারিখের হিসাব কর্মীরা সহজে রাখতে পারবেন।', 'ক্লিনিকের চালু রেকর্ড দিয়েই শুরু করুন: কার আসার কথা, কার সঙ্গে কথা হয়েছে, কে ফিরেছেন। কাজে লাগলে Simple-এর মতো টুল ব্যবহার করুন। কর্মীদের মধ্যে দায়িত্ব ভাগ ও তারিখ ঠিক করার কাজ সহজ করুন। চিকিৎসার সিদ্ধান্ত চিকিৎসকের হাতেই থাকবে।', 'কর্মীদের সময় বাঁচলে বা নিয়মিত চিকিৎসা চালাতে সুবিধা হলে ক্লিনিক সেটআপ ও সহায়তার জন্য মাসিক ফি দিতে পারে।', '["অনুমতি নিয়ে একটি ক্লিনিকের ফলোআপের কাজ দেখুন। কর্মী ও কথা বলতে রাজি রোগীদের কাছে না আসার কারণ জানুন।", "কাল্পনিক রেকর্ড দিয়ে কর্মীদের ছোট একটি কলের তালিকা ব্যবহার করতে দিন। বানানোর আগে চালু টুলের সঙ্গে তুলনা করুন।", "ক্লিনিকের অনুমতি ও রোগীর সম্মতি নিয়ে পরের ফলোআপ পর্যন্ত ছোট পরীক্ষা চালান। শুধু দরকারি তথ্য রেখে কর্মীদের সময়, যোগাযোগ ও ফেরত আসার হিসাব দেখুন।"]', 'কর্মীরা ব্যবস্থাটি ব্যবহার করে যান এবং ক্লিনিক পরের মাসের জন্য টাকা দিতে রাজি হয়।', 'কাল্পনিক রোগী, আসার তারিখ ও যোগাযোগের ফল দিয়ে কর্মীদের জন্য অ্যাপয়েন্টমেন্ট তালিকা বানান। চিকিৎসার পরামর্শ, আসল রোগীর তথ্য বা সরাসরি মেসেজ পাঠানো থাকবে না। কে কোন তথ্য দেখবেন ও কীভাবে মুছবেন, তা নকশায় রাখুন।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('workplace-heat', 'workplace-heat', 'manufacturing', '["gazipur", "dhaka"]', '[{"title": "World Bank · Heat risks in Bangladesh", "url": "https://www.worldbank.org/en/news/press-release/2025/09/16/bangladesh-faces-health-and-economic-risks-from-rising-temperature-world-bank", "date": "16 September 2025", "en": "The World Bank reports health and productivity risks from rising heat in Bangladesh. The study establishes the wider problem; the performance and economics of a particular factory retrofit still need site-level measurement.", "bn": "বিশ্বব্যাংকের প্রতিবেদনে বাংলাদেশের বাড়তি গরমে স্বাস্থ্য ও কর্মক্ষমতার ঝুঁকি উঠে এসেছে। নির্দিষ্ট কারখানায় পরিবর্তন এনে কতটা লাভ হবে, তা সেখানেই মাপতে হবে।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('workplace-heat', 'en', 'Hot workplaces put workers and production at risk', 'Factories need cooling improvements that work within their buildings and budgets.', 'Factory and warehouse operators with heat-exposed work areas.', 'Bangladesh’s rising heat creates health and productivity risks. For a founder, the useful question is narrower: which affordable changes can reduce heat in a particular work area without raising operating costs too far?', 'Which changes suit the building, process and season? Will the owner fund installation and upkeep, and do workers report a meaningful improvement?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('workplace-heat', 'bn', 'গরমে কর্মী ও উৎপাদন দুটোই ঝুঁকিতে পড়ে', 'ভবন ও বাজেটের সঙ্গে মানানসই শীতল করার ব্যবস্থা দরকার।', 'গরমে কাজ করতে হয় এমন কারখানা ও গুদামের পরিচালকেরা।', 'বাংলাদেশে বাড়তি গরম স্বাস্থ্য ও কাজের সক্ষমতায় ঝুঁকি তৈরি করছে। উদ্যোক্তার জন্য প্রশ্নটি ছোট করে আনা দরকার: একটি কাজের জায়গায় খরচ খুব না বাড়িয়ে কী বদলালে গরম কমে?', 'ভবন, কাজের ধরন ও মৌসুম অনুযায়ী কোন পরিবর্তন মানাবে? মালিক কি বসানো ও দেখভালের খরচ দেবেন? কর্মীরা কি বাস্তবে স্বস্তি পাবেন?');
INSERT INTO approaches (id, problem_id, kind, position, added_at, guides_json) VALUES ('cooler-workplaces', 'workplace-heat', 'service', '0', '2026-09-19', '["validation/customer-interviews", "validation/demand-without-building", "metrics/unit-economics"]');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('cooler-workplaces', 'en', 'Cooler workplaces, without a full rebuild', 'Help factories choose and maintain practical ways to reduce workplace heat.', 'Offer a site assessment and a small retrofit package, such as roof shading or improved ventilation, selected by a qualified engineer. Pair installation with measurement and maintenance so owners can judge what actually improves conditions.', 'The factory pays for an assessment and installation, with an optional maintenance contract. Quote against measured site needs, not promised productivity gains.', '["Visit one heat-exposed work area with its safety lead and workers. Record existing controls, conditions and the owner’s budget.", "Have a qualified engineer select one suitable change and agree on a paid pilot. Keep existing worker protections in place.", "Compare indoor conditions and energy use across comparable shifts, accounting for weather and production. Ask workers what changed."]', 'Measurably better conditions, worker acceptance and an owner willing to fund the next area.', 'Build a site-assessment form and a before-and-after comparison for indoor heat, outdoor weather, energy use and worker feedback. Mark missing readings clearly. Do not calculate health safety or productivity gains from temperature alone.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('cooler-workplaces', 'bn', 'বড় সংস্কার ছাড়াই কারখানায় গরম কমান', 'কাজের জায়গায় গরম কমানোর উপায় বাছাই ও দেখভালে সাহায্য করুন।', 'জায়গাটি দেখে উপযুক্ত প্রকৌশলী দিয়ে ছোট পরিবর্তনের পরিকল্পনা করুন। ছাদে ছায়া বা বাতাস চলাচল বাড়ানোর মতো ব্যবস্থা লাগতে পারে। বসানোর সঙ্গে ফল মাপা ও রক্ষণাবেক্ষণ রাখুন, যেন মালিক বুঝতে পারেন কোন কাজে সুবিধা হচ্ছে।', 'কারখানা পরিদর্শন ও ব্যবস্থা বসানোর জন্য টাকা দেবে। চাইলে রক্ষণাবেক্ষণের চুক্তি করবে। উৎপাদন বাড়বেই এমন প্রতিশ্রুতির বদলে জায়গার প্রয়োজন বুঝে দাম দিন।', '["নিরাপত্তার দায়িত্বে থাকা ব্যক্তি ও কর্মীদের সঙ্গে একটি গরম কাজের জায়গা দেখুন। চালু সুরক্ষা, পরিবেশ ও মালিকের বাজেট লিখুন।", "যোগ্য প্রকৌশলী দিয়ে একটি উপযুক্ত পরিবর্তন বাছুন এবং ফি নিয়ে পরীক্ষা ঠিক করুন। কর্মীদের চালু সুরক্ষা বহাল রাখুন।", "আবহাওয়া ও উৎপাদন মাথায় রেখে কাছাকাছি ধরনের শিফটে ভেতরের পরিবেশ ও বিদ্যুতের ব্যবহার তুলনা করুন। কর্মীদের অভিজ্ঞতা শুনুন।"]', 'পরিবেশের উন্নতি মাপে ধরা পড়ে, কর্মীরা সুবিধা পান এবং মালিক আরেকটি জায়গায় খরচ করতে চান।', 'পরিদর্শনের ফর্ম ও আগে-পরে তুলনার নমুনা বানান। ভেতরের গরম, বাইরের আবহাওয়া, বিদ্যুতের ব্যবহার ও কর্মীদের মতামত রাখুন। রিডিং না থাকলে স্পষ্ট দেখান। শুধু তাপমাত্রা থেকে স্বাস্থ্যের নিরাপত্তা বা উৎপাদন বৃদ্ধির হিসাব করবেন না।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('solar-maintenance', 'solar-maintenance', 'energy', '["anywhere"]', '[{"title": "IEEFA · Rooftop solar maintenance in Bangladesh", "url": "https://ieefa.org/resources/rooftop-solars-time-shine-bangladesh", "date": "18 August 2025", "en": "IEEFA identifies maintenance, soiling and monitoring gaps in Bangladesh’s rooftop-solar rollout. It recommends provision for long-term upkeep. This is a service opportunity to test, not a forecast of recoverable energy at a given site.", "bn": "IEEFA বাংলাদেশের ছাদের সৌরবিদ্যুৎ ব্যবস্থায় রক্ষণাবেক্ষণ, ময়লা জমা ও পর্যবেক্ষণের ঘাটতি তুলেছে। দীর্ঘমেয়াদি দেখভালের ব্যবস্থা রাখার পরামর্শ দিয়েছে। কোনো স্থাপনায় কত বিদ্যুৎ বাড়বে, তা আলাদা করে মাপতে হবে।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('solar-maintenance', 'en', 'Solar installations need care after handover', 'Owners need to know when output drops and who will fix the cause.', 'Rooftop-solar owners and installers managing several customer sites.', 'Bangladesh’s rooftop-solar expansion brings an ongoing maintenance need. IEEFA highlights soiling, service provision and independent monitoring. A focused business could serve sites whose handover left no dependable upkeep.', 'What is already covered by the installer or warranty? How much lost output is avoidable, and can technicians serve several nearby sites profitably?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('solar-maintenance', 'bn', 'সোলার বসানোর পরও দেখভাল দরকার', 'বিদ্যুৎ কম হলে মালিকের জানা দরকার কেন কমছে আর কে ঠিক করবেন।', 'ছাদের সোলারের মালিক ও একাধিক গ্রাহকের স্থাপনা দেখেন এমন ইনস্টলার।', 'বাংলাদেশে ছাদের সোলার বাড়ার সঙ্গে নিয়মিত রক্ষণাবেক্ষণের প্রয়োজনও বাড়ছে। IEEFA ময়লা জমা, সেবা ও আলাদা পর্যবেক্ষণের বিষয় তুলেছে। যেখানে বসানোর পর নির্ভরযোগ্য দেখভাল নেই, সেখানে সেবার সুযোগ খোঁজা যায়।', 'ইনস্টলারের চুক্তি বা ওয়ারেন্টিতে কী আছে? উৎপাদনের কতটা ক্ষতি এড়ানো যায়? কাছাকাছি কয়েকটি স্থাপনা দেখে টেকনিশিয়ানের খরচ উঠবে কি?');
INSERT INTO approaches (id, problem_id, kind, position, added_at, guides_json) VALUES ('solar-upkeep', 'solar-maintenance', 'service', '0', '2026-09-19', '["validation/customer-interviews", "validation/demand-without-building", "metrics/unit-economics"]');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('solar-upkeep', 'en', 'Keep rooftop solar producing', 'Spot avoidable output losses and get the right technician to fix them.', 'Combine a simple output check with scheduled maintenance and fault resolution for existing solar sites. Work with qualified technicians and the original installer. Keep weather, grid outages and equipment faults separate when explaining lost generation.', 'Owners or installation firms pay per site for monitoring and upkeep. Quote repairs separately and respect existing warranties.', '["Interview three owners and one installer. Review their maintenance contracts, fault history and available generation records with permission.", "Offer a paid inspection at one site with a qualified technician. Identify a fixable issue without duplicating warranty work.", "Track the repair, service cost and subsequent output, accounting for sunlight and grid availability. Offer a recurring contract if the value is clear."]', 'A paid renewal based on verified maintenance work and useful reporting.', 'Prototype a site list, generation log and repair queue using synthetic readings. Distinguish missing data, grid outages and suspected equipment faults. Do not remotely control equipment or promise energy savings.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('solar-upkeep', 'bn', 'ছাদের সোলার থেকে বিদ্যুৎ উৎপাদন সচল রাখুন', 'এড়ানো যায় এমন ক্ষতি ধরুন, ঠিক করার জন্য উপযুক্ত টেকনিশিয়ান দিন।', 'চালু সোলারের উৎপাদন দেখা, নিয়মিত রক্ষণাবেক্ষণ ও ত্রুটি সারানো এক সেবায় আনুন। যোগ্য টেকনিশিয়ান ও মূল ইনস্টলারের সঙ্গে কাজ করুন। উৎপাদন কমার কারণ বোঝাতে আবহাওয়া, গ্রিড বন্ধ থাকা ও যন্ত্রের ত্রুটি আলাদা করুন।', 'মালিক বা ইনস্টলার প্রতি স্থাপনার জন্য পর্যবেক্ষণ ও দেখভালের ফি দেবেন। মেরামতের দাম আলাদা দিন এবং চালু ওয়ারেন্টি মেনে কাজ করুন।', '["তিনজন মালিক ও একজন ইনস্টলারের সঙ্গে কথা বলুন। অনুমতি নিয়ে রক্ষণাবেক্ষণের চুক্তি, ত্রুটির ইতিহাস ও উৎপাদনের রেকর্ড দেখুন।", "যোগ্য টেকনিশিয়ান নিয়ে একটি স্থাপনায় ফি দিয়ে পরিদর্শনের প্রস্তাব দিন। ওয়ারেন্টির কাজ আবার না করে ঠিক করা যায় এমন ঘাটতি খুঁজুন।", "মেরামত, সেবার খরচ ও পরের উৎপাদন লিখুন। রোদ ও গ্রিড চালু থাকার সময় ধরে তুলনা করুন। উপকার স্পষ্ট হলে নিয়মিত চুক্তির প্রস্তাব দিন।"]', 'যাচাই করা কাজ ও দরকারি রিপোর্ট দেখে গ্রাহক টাকা দিয়ে চুক্তি নবায়ন করেন।', 'নমুনা রিডিং দিয়ে স্থাপনার তালিকা, উৎপাদনের হিসাব ও মেরামতের কাজের তালিকা বানান। তথ্য না থাকা, গ্রিড বন্ধ থাকা ও সম্ভাব্য যন্ত্রের ত্রুটি আলাদা করুন। দূর থেকে যন্ত্র চালাবেন না বা বিদ্যুৎ সাশ্রয়ের প্রতিশ্রুতি দেবেন না।');
INSERT INTO organizations (id, slug, website, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_reverse-resources', 'reverse-resources', 'https://www.reverseresources.net/', '["startup"]', '["Reverse Resources", "RR"]', '["https://www.reverseresources.net/", "https://globalfashionagenda.org/news-article/transforming-post-industrial-textile-waste-in-bangladesh/"]', '2026-09-19', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_reverse-resources', 'en', 'Reverse Resources', 'A textile-waste traceability platform connecting manufacturers, waste handlers and recyclers, with documented work in Bangladesh.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_reverse-resources', 'bn', 'রিভার্স রিসোর্সেস', 'কাপড়ের বর্জ্যের গতিপথের তথ্য রাখার প্ল্যাটফর্ম। প্রস্তুতকারক, বর্জ্য সংগ্রহকারী ও রিসাইক্লারদের যুক্ত করে। বাংলাদেশেও কাজের প্রকাশিত তথ্য আছে।');
INSERT INTO connections (id, organization_id, problem_id, stage, work_en, work_bn, evidence_url, review_scope, reviewed_at) VALUES ('connection_reverse-resources_offcuts', 'org_reverse-resources', 'garment-offcuts', 'live', 'Supports textile-waste traceability in Bangladesh’s SWITCH to Upstream Circularity pilot.', 'বাংলাদেশের SWITCH to Upstream Circularity উদ্যোগে কাপড়ের বর্জ্যের গতিপথের তথ্য রাখতে কাজ করছে।', 'https://globalfashionagenda.org/news-article/transforming-post-industrial-textile-waste-in-bangladesh/', 'public-source-context', '2026-09-19T00:00:00.000Z');
